"""The Events read model against goldens generated by the OLD code (review 015):
``python -m projectzero.ops.parity_events_read goldens``."""

from __future__ import annotations

import json
from typing import Any

import pytest

from projectzero.ops.parity_events_read import CLOCKS, GOLDEN, OLD_CRASH_SETS, compare_goldens, goldens_input

GOLDEN_DOC: dict[str, Any] = json.loads(GOLDEN.read_text(encoding="utf-8"))


def test_provenance_is_the_clean_old_revision() -> None:
    prov = GOLDEN_DOC["provenance"]
    assert prov["old_revision"] == "6c739b9cb6ca2517b845e381d39a36c50eccc59e" and prov["old_dirty"] is False
    assert prov["clocks"] == list(CLOCKS)


def test_the_golden_input_is_the_current_corpus() -> None:
    assert GOLDEN_DOC["input"] == json.loads(json.dumps(goldens_input()))


def test_the_port_matches_the_old_code_at_every_clock() -> None:
    assert compare_goldens(GOLDEN_DOC) == []


def test_the_corpus_reaches_every_branch() -> None:
    """Guard against a vacuous match: the synthetic set really exercises the rules."""
    rules = GOLDEN_DOC["expected"]["sets"]["rules"]["2026-11-11T12:00:00"]
    evs = rules["events"]["ok"]["events"]
    labels = {e["eligibility"]["label"] for e in evs}
    assert labels == {"HIGH-SIGNAL", "GENERAL EVENT", "NEEDS REVIEW", "VERIFIED BY YOU", "CANCELLED", "NO DATE", "PAST"}
    assert {e["when"]["group"] for e in evs} == {"weekend", "next7", "later", "past", "undated"}
    assert {e["action"]["state"] for e in evs} == {"open", "unknown", "waitlist", "sold_out"}
    assert {e["price_state"] for e in evs} == {"free", "paid", "price range", "price unknown", "sold out"}
    assert any(e["sc"]["human"] for e in evs) and any(e.get("scout") for e in evs)
    assert rules["events"]["ok"]["scout_reports"] and all(len(v["ok"]) for k, v in rules["wsig"].items() if k == "30")


@pytest.mark.parametrize("name", OLD_CRASH_SETS)
def test_the_old_crashes_are_answered_here(name: str) -> None:
    """The intentional difference: where the old code raised (the whole page / the weekend planner), the port reads
    the bad value as no date and answers; the comparison allows exactly that (see ``compare_goldens``)."""
    per = GOLDEN_DOC["expected"]["sets"][name]
    assert any("raises" in v for c in per.values() for v in [c["events"], *c["weekend"].values()])
